{"command": "cd /workspace && echo "--- full log ---" && cat out/cde_runs.jsonl && echo && echo "--- last run per target (worksheet of record) ---" && python3 -c "
import json
runs={}
for line in open('out/cde_runs.jsonl'):
    r=json.loads(line); runs[r['target_id']]=r
for tid in sorted(runs):
    r=runs[tid]
    print(f\"{tid}  L{r['cde_level']}  occ={r['occupancy_basis']}  est={r['nc_casualty_estimate']}  ncv={r['ncv']}  auth={r['approval_authority']}  nsl={r['nsl_within_cer']}  cmd={r['cmd']}\")
""}

